DROP TABLE IF EXISTS transactions, loans, accounts, customers CASCADE;
CREATE TABLE customers(customer_id INT PRIMARY KEY,age INT,state VARCHAR(2),customer_segment VARCHAR(30),annual_income INT,credit_score INT,join_date DATE);
CREATE TABLE accounts(account_id INT PRIMARY KEY,customer_id INT REFERENCES customers(customer_id),account_type VARCHAR(30),balance NUMERIC(12,2),opened_date DATE);
CREATE TABLE loans(loan_id INT PRIMARY KEY,customer_id INT REFERENCES customers(customer_id),loan_type VARCHAR(40),loan_amount INT,interest_rate NUMERIC(5,2),term_months INT,loan_status VARCHAR(20),origination_date DATE);
CREATE TABLE transactions(transaction_id INT PRIMARY KEY,account_id INT REFERENCES accounts(account_id),transaction_date DATE,transaction_type VARCHAR(30),amount NUMERIC(12,2));

